import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { changeMembershipHandler } from "../handlers/changeMembershipHandler";
import type { ApiError } from "../runtime/client";
import type { ChangeMembershipRequest } from "../types/ChangeMembershipRequest";

type Data = Awaited<ReturnType<typeof changeMembershipHandler>>;
type Vars = ChangeMembershipRequest;

export function useChangeMembership(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => changeMembershipHandler(vars),
    ...options,
  });
}
